ax2.set_ylabel("Flow Rate", fontsize=11)
ax2.set_title("Rate Dynamics (Flows & Auxiliaries)", fontsize=12)
ax2.grid(True, linestyle="--", alpha=0.5)
ax2.legend(loc="best", framealpha=0.9)

plt.tight_layout()
plt.show()
